"""FastAPI app generated by intpot."""


from pathlib import Path

from fastapi import FastAPI as _intpot_fastapi_FastAPI, Body as _intpot_fastapi_Body

STOCK_UNITS = 150

UNIT_PRICE = 12

def reservation_cost(quantity: int, packs: int) -> int:
    if quantity * packs > STOCK_UNITS:
        raise ValueError('reservation exceeds available stock')
    return quantity * packs * UNIT_PRICE

app = _intpot_fastapi_FastAPI(title='inventory')
_intpot_required = object()


def _reserve_inventory_impl(
    quantity: int = _intpot_required,
    packs: int = 1,
    receipt: str = '',
) -> dict:
    """Reserve a bounded number of inventory units without mutable server state."""
    if quantity is _intpot_required:
        raise TypeError('Missing required argument: quantity')
    cost = reservation_cost(quantity, packs)
    result = {"quantity": quantity, "packs": packs, "cost": cost}
    if receipt:
        Path(receipt).write_text(str(result), encoding="utf-8")
    return result


@app.post(
    '/reserve_inventory',
    name='reserve_inventory',
    summary='Reserve a bounded number of inventory units without mutable server state.',
    description='Reserve a bounded number of inventory units without mutable server state.',
)
def reserve_inventory(
    quantity: int = _intpot_fastapi_Body(..., ge=1, le=100),
    packs: int = _intpot_fastapi_Body(default=1, ge=1, le=5),
    receipt: str = _intpot_fastapi_Body(default=''),
) -> dict:
    """Reserve a bounded number of inventory units without mutable server state."""

    return _reserve_inventory_impl(quantity, packs, receipt)


if __name__ == "__main__":
    import uvicorn as _intpot_api_uvicorn

    # Loopback only. Change to "0.0.0.0" to expose this on the network.
    _intpot_api_uvicorn.run(app, host="127.0.0.1", port=8000)
